'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID();
const day=(n=0)=>{let d=new Date();d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const subjects=['语法','阅读','完形填空','听力','词汇','EJU 化学'],glyph=['文','読','穴','聴','あ','化'],colors=['#efaa88','#b6c8aa','#d7bbda','#a9cbd3','#efcf84','#bbbfdb'],codes=['GRAMMAR','READING','CLOZE','LISTENING','WORDS','CHEMISTRY'],states=['待复习','易错','已掌握'],levels=['N2','N3','EJU','待确认'],pages=['学习工作台','题目档案','复习中心','阶段目标','学习统计'];
const paths=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M3 6h7l2 2h9v12H3z','M3 11a9 9 0 1 1 2 7 M3 5v6h6 M12 8v5l3 2','M5 21V3 M6 4c5-3 8 3 14 0v10c-6 3-9-3-14 0','M4 20h17 M7 16v-5 M12 16V4 M17 16V8'];const icon=i=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[i]+'"/></svg>';
let db,qs=[],works=[],logs=[],goals=[],page=pages[0],f={},session=[],pos=0,mode='标准解析',photoURL='',editWork='';
const stores=['questions','works','logs','goals'];function txWrite(changes){return new Promise((ok,no)=>{const t=db.transaction([...new Set(changes.map(c=>c[0]))],'readwrite');for(const [name,v] of changes)t.objectStore(name).put(v);t.oncomplete=ok;t.onerror=()=>no(t.error);t.onabort=()=>no(t.error)})}
async function reload(){[qs,works,logs,goals]=await Promise.all(stores.map(s=>new Promise((ok,no)=>{let r=db.transaction(s).objectStore(s).getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})));qs.sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created)}
const examples=[
['语法','「ものの」的用法','免許は取ったものの、まだ運転していない。','虽然拿到了驾照，但还没开过车。','ものの表示转折。前半句已成事实，后半句与预期不同。','めんきょはとったものの、まだうんてんしていない。','转折'],
['阅读','寻找作者的判断依据','便利な道具は多い。しかし、使い方を考える時間も必要だ。作者强调什么？','使用工具前也要花时间想一想怎么用。','しかし之后的内容是作者强调的观点。','べんりなどうぐはおおい。しかし、つかいかたをかんがえるじかんもひつようだ。','观点理解'],
['词汇','「見直す」的读法与词义','計画を見直す。请写出「見直す」的读音和意思。','みなおす。重新审视、重新考虑。','此处指再看一次计划并考虑调整。','けいかくをみなおす。','动词'],
['完形填空','选择合适的接续词','雨が強くなった。（　）、試合は続いた。应填「それでも」还是「そのため」？','それでも','雨更大了，比赛却仍在继续，前后形成转折。','あめがつよくなった。それでも、しあいはつづいた。','接续词'],
['EJU 化学','水的物质的量','取 36 g 水，摩尔质量按 18 g/mol 计算，物质的量是多少？','2 mol','n = m / M = 36 / 18 = 2 mol。','','物质的量']
];function seed(){return examples.map(([subject,title,prompt,answer,analysis,kana,tag],i)=>({id:'example'+i,subject,title,prompt,answer,analysis,kana,tag:'入门练习 '+tag,stage:i===4?'EJU':'N2',status:'待复习',date:day(),created:10-i,due:day(),count:0,translation:i===1?'方便的工具有很多。不过，我们也需要花点时间想想怎么用。':i===0?answer:'',key:i===1?'第1段，第2句':'',plain:i===4?'n = m / M = 36 g / (18 g/mol) = 2 mol':'',kanji:i===2?'見直す':'',meaning:i===2?'重新审视、重新考虑':'',example:true}))}
async function init(){let r=indexedDB.open('nihongo-studio',1);r.onupgradeneeded=()=>stores.forEach(s=>r.result.createObjectStore(s,{keyPath:'id'}));db=await new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});await reload();if(!qs.length&&!works.length){await txWrite(seed().map(q=>['questions',q]));await reload()}render()}
function go(p,filter={}){page=p;f=filter;render();scrollTo(0,0)}
function render(){document.querySelector('#crumb').textContent=page;$('#nav').innerHTML=pages.map((p,i)=>'<button class="'+(p===page?'active':'')+'" onclick="go(pages['+i+'])">'+icon(i)+p+'</button>').join('');$('#view').innerHTML=heading()+[home,bank,review,targets,statistics][pages.indexOf(page)]();if(page===pages[1])list()}
const btn=(s,fn,cl='light')=>'<button class="'+cl+'" onclick="'+fn+'">'+s+'</button>',options=(arr,v)=>arr.map(a=>'<option '+(a===v?'selected':'')+'>'+esc(a)+'</option>').join('');
function heading(){let subtitle=page===pages[0]?new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long',year:'numeric'}):['','按科目、阶段和标签整理练习','按到期时间回顾题目','记录每一阶段想完成的练习','从实际练习记录追踪薄弱点'][pages.indexOf(page)];return '<div class="heading"><div><h1>'+page+'</h1><div class="date">'+subtitle+'</div></div>'+btn('＋ 上传作业','upload()','primary')+'</div>'}
const due=()=>qs.filter(q=>q.due<=day()).sort((a,b)=>a.due.localeCompare(b.due));function daily(){return [...due(),...qs.filter(q=>q.due>day())].filter(q=>!logs.some(l=>l.date===day()&&l.qid===q.id)).slice(0,3)}
function stats(){let recent=logs.filter(l=>l.date>=day(-6));return '<div class="stats">'+[[recent.length,'练习次数'],[new Set(recent.map(l=>l.date)).size,'学习天数'],[new Set(recent.filter(l=>l.status==="已掌握").map(l=>l.qid)).size,'掌握题目']].map(([v,n])=>'<div><b>'+v+'</b><small>'+n+'</small></div>').join('')+'</div><div class="week">'+Array.from({length:7},(_,i)=>{let d=day(i-6),n=recent.filter(l=>l.date===d).length;return '<div class="'+(i===6?'today':'')+'" title="'+d+' · '+n+' 次"><small>'+('日一二三四五六'[new Date(d+'T12:00').getDay()])+'</small><i '+(n?'style="background:#96ad88"':'')+'></i><small>'+n+'</small></div>'}).join('')+'</div>'}
const sh=(a,b,right='')=>'<div class="sectionhead"><h2>'+a+' <span class="eng">'+b+'</span></h2>'+right+'</div>';
function home(){let d=daily();return '<div class="hero"><div class="art" aria-hidden="true"><div class="disc"></div><div class="sleeve"><b>N2</b><small>NIHONGO / STUDY</small></div></div><div class="kicker"><b>●</b> DAILY SESSION</div><h2>今日研习计划</h2><p>'+ (d.length?'从 '+d.length+' 道练习开始，逐步巩固薄弱点。':'今天的练习已完成，可继续自由复习。')+'</p>'+btn('▷　开始练习','startDaily()','')+'</div><div class="grid"><div class="panel">'+sh('每日练习','PRACTICE QUEUE','<span class="count">'+d.length+' 题</span>')+(d.length?d.map((q,i)=>track(q,i)).join(''):'<p class="empty">今日练习已完成。</p>')+'</div><div class="panel">'+sh('近七日学习','WEEKLY STATS')+stats()+'</div></div><div class="sectionhead catalog"><h2>科目研习 <span class="eng">SUBJECT COLLECTION</span></h2>'+btn('全部题目 ↗',"go(pages[1])",'')+'</div><div class="cards">'+subjects.map((s,i)=>'<button class="card" onclick="go(pages[1],{subject:subjects['+i+']})"><div class="cover" style="background:'+colors[i]+'"><small>'+codes[i]+'</small><b>'+glyph[i]+'</b></div><footer><strong>'+s+'</strong><small>'+qs.filter(q=>q.subject===s).length+' 道题目</small></footer></button>').join('')+'</div>'}
function track(q,i){let j=subjects.indexOf(q.subject);return '<button class="track" onclick="begin([\''+q.id+'\'])"><span class="num">0'+(i+1)+'</span><span class="tile" style="background:'+colors[j]+'">'+glyph[j]+'</span><span><strong>'+esc(q.title)+'</strong><small>'+esc(q.stage)+' · '+esc(q.subject)+' · '+(q.example?'内置练习':'个人题目')+'</small></span><span class="play">▷</span></button>'}
function filterSelect(k,arr,placeholder){return '<select aria-label="'+placeholder+'" onchange="f.'+k+'=this.value;list()"><option value="">'+placeholder+'</option>'+options(arr,f[k])+'</select>'}
function bank(){return '<div class="panel"><div class="between"><h2>全部题目</h2>'+btn('＋ 新增题目','edit()','dark')+'</div><div class="filters"><input id="searchBox" placeholder="搜索题干、作业名或标签" value="'+esc(f.text)+'" oninput="f.text=this.value;list()">'+filterSelect('subject',subjects,'全部科目')+filterSelect('stage',levels,'全部阶段')+filterSelect('status',states,'全部状态')+'<input type="date" aria-label="练习日期" value="'+esc(f.date)+'" onchange="f.date=this.value;list()">'+btn('重置',"go(pages[1])")+'</div><div id="results"></div></div><div class="panel" style="margin-top:16px">'+sh('作业图片','HOMEWORK')+(works.length?works.map(w=>'<div class="entry"><span>'+esc(w.title)+'<small class="sub">　'+esc(w.date)+'</small></span>'+btn('继续补录',"edit(null,'"+w.id+"')")+'</div>').join(''):'<p class="empty">上传作业图片后，可在这里继续补录题目。</p>')+'</div>'}
function list(){let rows=qs.filter(q=>['subject','stage','status','date'].every(k=>!f[k]||q[k]===f[k])&&[q.title,q.prompt,q.tag,q.kanji,q.kana,q.meaning,works.find(w=>w.id===q.work)?.title].join(' ').toLowerCase().includes((f.text||'').toLowerCase()));$('#results').innerHTML='<div class="sub">'+rows.length+' 道题目</div>'+rows.map(row).join('')+(rows.length?'':'<p class="empty">没有符合条件的题目。</p>')}
function row(q){return '<div class="entry"><button onclick="detail(\''+q.id+'\')"><strong>'+esc(q.title)+'</strong><div>'+[q.stage,q.subject,q.status,...(q.tag||'').split(/[,，\s]+/).filter(Boolean)].map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div></button>'+btn('查看 ›',"detail('"+q.id+"')",'')+'</div>'}
function review(){let d=due();return '<div class="panel">'+sh('到期复习','SPACED REVIEW',btn('开始复习','startDue()','dark'))+'<p class="date">今日到期 '+d.length+' 题 · 根据每次掌握情况安排下次复习</p><div class="actions">'+btn('只看易错题',"go(pages[1],{status:'易错'})")+'</div>'+d.map(row).join('')+(d.length?'':'<p class="empty">当前没有到期题目。</p>')+'</div>'}
function targets(){return '<div class="panel narrow">'+sh('阶段目标','GOALS',btn('＋ 添加目标','goalForm()','dark'))+(goals.length?goals.map(g=>{let n=new Set(logs.filter(l=>l.date>=g.start&&(!g.end||l.date<=g.end)&&(!g.subject||l.subject===g.subject)&&(!g.stage||l.stage===g.stage)).map(l=>l.qid)).size;return '<div class="detail"><b>'+esc(g.title)+'</b><p class="date">'+esc(g.start)+' 至 '+esc(g.end||'待确认')+' · '+esc(g.subject||'全部科目')+' · '+esc(g.stage||'全部阶段')+'</p><div class="bar"><i style="width:'+Math.min(100,n/g.total*100)+'%"></i></div>'+n+' / '+g.total+' 道练习</div>'}).join(''):'<p class="empty">设置目标题量，完成练习后会自动累计进度。</p>')+'<p class="date">N2 考试日期 · 待确认</p></div>'}
function statistics(){return '<div class="panel narrow">'+sh('近七日记录','ACTIVITY')+stats()+'</div><div class="panel narrow" style="margin-top:16px">'+sh('科目掌握情况','SUBJECT PROGRESS')+subjects.map(s=>{let a=qs.filter(q=>q.subject===s),m=a.filter(q=>q.status===states[2]).length,w=a.filter(q=>q.status===states[1]).length;return '<div class="detail"><div class="between"><b>'+s+'</b>'+btn('易错 '+w+' ›',"go(pages[1],{subject:'"+s+"',status:'易错'})",'')+'</div><div class="bar"><i style="width:'+100*m/(a.length||1)+'%"></i></div><span class="sub">已掌握 '+m+' / '+a.length+' 题</span></div>'}).join('')+'</div><div class="panel narrow" style="margin-top:16px">'+sh('数据备份','BACKUP')+'<p class="date">记录保存在此浏览器。可导出含作业原图的备份，在另一台设备导入。</p><div class="actions">'+btn('导出备份','backup()')+btn('导入备份','restoreForm()')+'</div></div>'}
function modal(title,body){$('#modal').innerHTML='<div class="between"><h2>'+title+'</h2>'+btn('×','dlg.close()','close')+'</div>'+body;if(!dlg.open)dlg.showModal();dlg.scrollTop=0}
const field=(key,name,v='',type='text',required=false)=>'<label>'+name+'<input name="'+key+'" type="'+type+'" value="'+esc(v)+'" '+(required?'required':'')+'></label>',area=(key,name,v='')=>'<label>'+name+'<textarea name="'+key+'" placeholder="待确认">'+esc(v)+'</textarea></label>',sel=(k,name,arr,v)=>'<label>'+name+'<select name="'+k+'">'+options(arr,v)+'</select></label>';
function upload(){modal('上传作业','<form onsubmit="saveWork(event)">'+field('title','作业名称','','text',true)+'<div class="fields">'+sel('subject','科目',subjects)+sel('stage','阶段',levels)+'</div>'+field('date','练习日期',day(),'date',true)+'<label>作业原图（可多选）<input type="file" name="images" accept="image/*" multiple required></label><button class="dark">保存并补录第一题</button></form>')}
async function saveWork(e){e.preventDefault();let form=e.target,d=new FormData(form),images=d.getAll('images');let w={id:uid(),title:d.get('title'),date:d.get('date'),subject:d.get('subject'),stage:d.get('stage'),images};await guarded(form,async()=>{await txWrite([['works',w]]);await reload();render();edit(null,w.id)})}
async function guarded(form,fn){let buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){alert('保存失败，请检查设备可用空间后重试。')}finally{buttons.forEach(b=>b.disabled=false)}}
function pictures(w){if(!w?.images?.length)return '';return '<label>查看作业原图<select id="picSel" onchange="showPhoto(this.value)">'+w.images.map((_,i)=>'<option value="'+i+'">第 '+(i+1)+' 张</option>').join('')+'</select></label><img id="photo" class="photo" alt="作业原图">'}
function showPhoto(i){if(photoURL)URL.revokeObjectURL(photoURL);let img=works.find(w=>w.id===editWork)?.images[i];if(img&&$('#photo'))$('#photo').src=photoURL=URL.createObjectURL(img)}
function edit(id=null,wid=''){let q=qs.find(q=>q.id===id)||{},w=works.find(w=>w.id===(q.work||wid));editWork=w?.id||'';modal(id?'编辑题目':'新增题目','<form onsubmit="saveQ(event)"> <input type="hidden" name="id" value="'+(id||'')+'">'+pictures(w)+(w?'<div class="date">关联作业 · '+esc(w.title)+'</div>':'')+field('title','题号或标题',q.title|| (w?'第 '+(qs.filter(q=>q.work===w.id).length+1)+' 题':''),'text',true)+'<div class="fields">'+sel('subject','科目',subjects,q.subject||w?.subject)+sel('stage','阶段',levels,q.stage||w?.stage)+field('date','练习日期',q.date||w?.date||day(),'date',true)+sel('status','掌握状态',states,q.status)+'</div>'+area('prompt','题干',q.prompt)+area('answer','答案',q.answer)+area('analysis','解析',q.analysis)+'<div class="fields">'+field('kanji','日文汉字',q.kanji)+field('meaning','中文意思',q.meaning)+'</div>'+area('kana','纯假名版 / 假名读法',q.kana)+area('translation','像 N2能力高中生翻译的样子',q.translation)+field('key','关键句与段落 / 行数',q.key)+area('plain','公式或特殊字符的纯文本回退',q.plain)+field('tag','标签（空格或逗号分隔）',q.tag)+'<div class="actions"><button class="dark">保存题目</button><button name="more" class="light">保存并继续新增</button></div></form>');showPhoto(0)}
async function saveQ(e){e.preventDefault();let form=e.target,d=Object.fromEntries(new FormData(form)),old=qs.find(q=>q.id===d.id),more=e.submitter?.name==='more',w=editWork,q={...old,...d,id:d.id||uid(),work:w,created:old?.created||Date.now(),count:old?.count||0,due:old?.status===d.status?old.due:day(d.status==='已掌握'?7:0)};await guarded(form,async()=>{await txWrite([['questions',q]]);await reload();render();if(more)edit(null,w);else detail(q.id)})}
const labels={prompt:'题干',answer:'答案',analysis:'解析',kana:'纯假名版',kanji:'日文汉字',meaning:'中文意思',translation:'像 N2能力高中生翻译的样子',key:'关键句 · 段落或行数',plain:'纯文本回退'};
const display=(q,keys)=>keys.map(k=>'<div class="detail"><small>'+labels[k]+'</small>'+esc(q[k]||'待确认')+'</div>').join('');
function detail(id){let q=qs.find(q=>q.id===id),w=works.find(w=>w.id===q.work);editWork=w?.id||'';modal(esc(q.title),'<div class="sub">'+esc([q.stage,q.subject,q.date,q.status].join(' · '))+'</div>'+pictures(w)+display(q,Object.keys(labels))+'<div class="actions">'+btn('编辑题目',"edit('"+id+"')",'dark')+btn('练习此题',"begin(['"+id+"'])")+'</div>');showPhoto(0)}
function startDaily(){begin(daily().length?daily().map(q=>q.id):qs.slice(0,3).map(q=>q.id))}function startDue(){begin(due().map(q=>q.id))}
function begin(ids){if(!ids.length)return modal('复习完成','<p>当前没有到期题目。</p>');session=ids;pos=0;practice(false)}
function practice(reveal){let q=qs.find(q=>q.id===session[pos]),w=works.find(w=>w.id===q.work);editWork=w?.id||'';modal('练习 '+(pos+1)+' / '+session.length,'<div class="sub">'+esc(q.stage)+' · '+esc(q.subject)+'</div><h3 class="focus">'+esc(q.title)+'</h3>'+pictures(w)+display(q,['prompt'])+(reveal?sel('mode','输出方式',['标准解析','纯假名版','像 N2能力高中生翻译的样子','纯文本回退'],mode)+'<div id="out"></div><div class="actions">'+states.map((s,i)=>btn(s,'grade('+i+')',i===2?'dark':'light')).join('')+'</div>':'<div class="actions">'+btn('显示答案','practice(true)','dark')+'</div>'));showPhoto(0);if(reveal){let el=$('[name=mode]');el.onchange=()=>{mode=el.value;$('#out').innerHTML=display(q,mode==='标准解析'?['answer','analysis','key']:mode==='纯假名版'?['kana']:mode==='纯文本回退'?['plain']:['translation'])};el.onchange()}}
async function grade(i){let q=qs.find(q=>q.id===session[pos]),count=i===2?q.count+1:0,updated={...q,count,status:states[i],due:day(i===2?[3,7,14,30][Math.min(count-1,3)]:i===1?1:2)};await guarded($('#modal'),async()=>{await txWrite([['questions',updated],['logs',{id:uid(),qid:q.id,date:day(),subject:q.subject,stage:q.stage,status:states[i]}]]);await reload();render();if(++pos<session.length)practice(false);else modal('本轮练习完成','<p>已记录 '+session.length+' 道题的掌握情况，并安排下次复习。</p><div class="actions">'+btn('返回学习空间','dlg.close()','dark')+'</div>')})}
function goalForm(){modal('添加阶段目标','<form onsubmit="saveGoal(event)">'+field('title','目标名称','','text',true)+'<div class="fields">'+sel('subject','科目',['全部科目',...subjects])+sel('stage','阶段',['全部阶段',...levels])+field('start','开始日期',day(),'date',true)+field('end','结束日期（可待确认）','','date')+'</div><label>目标题量<input type="number" name="total" value="10" min="1" required></label><button class="dark">保存目标</button></form>')}
async function saveGoal(e){e.preventDefault();let form=e.target,g=Object.fromEntries(new FormData(form));if(g.end&&g.end<g.start)return alert('结束日期须在开始日期之后或同一天。');g.id=uid();g.total=Number(g.total);if(g.stage==='全部阶段')g.stage='';if(g.subject==='全部科目')g.subject='';await guarded(form,async()=>{await txWrite([['goals',g]]);await reload();dlg.close();render()})}
init().catch(()=>{$('#view').textContent='无法打开本机学习数据库，请允许浏览器存储并重新加载。'});
async function backup(){try{await reload();let packed=await Promise.all(works.map(async w=>({...w,images:await Promise.all(w.images.map(blob=>new Promise((ok,no)=>{let r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(blob)})))})));let url=URL.createObjectURL(new Blob([JSON.stringify({version:1,questions:qs,works:packed,logs,goals})],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='日语研习室-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{alert('备份生成失败，请重试。')}}
function restoreForm(){modal('导入学习备份','<form onsubmit="restore(event)"><p>将合并记录。相同编号的题目和作业会使用备份中的版本。</p><label>选择 JSON 备份<input type="file" name="file" accept=".json,application/json" required></label><button class="dark">确认导入</button></form>')}
async function restore(e){e.preventDefault();let form=e.target;await guarded(form,async()=>{let data;try{data=JSON.parse(await form.file.files[0].text());if(data.version!==1||!stores.every(k=>Array.isArray(data[k])&&data[k].every(v=>typeof v.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(v.id))))throw Error();if(!data.questions.every(q=>subjects.includes(q.subject)&&states.includes(q.status)&&typeof q.date==='string'&&typeof q.title==='string'&&typeof q.due==='string'&&(!q.tag||typeof q.tag==='string')))throw Error();for(let w of data.works){w.images=await Promise.all(w.images.map(async s=>{if(!/^data:image\/[a-zA-Z0-9.+-]+;base64,/.test(s))throw Error();return (await fetch(s)).blob()}))}if(!data.goals.every(g=>Number.isInteger(g.total)&&g.total>0))throw Error()}catch{return alert('文件格式不正确，请选择本应用导出的完整备份。')}let changes=stores.flatMap(k=>data[k].map(v=>[k,v]));if(changes.length)await txWrite(changes);await reload();render();modal('导入完成','<p>学习记录和作业原图已合并。</p>')})}
